async function getAuthorsWithBooks(authorIds) {
  const authors = await Author.findAll({ 
    where: { id: authorIds } 
  });

  const result = [];
  for (const author of authors) {
    const books = await Book.findAll({ 
      where: { authorId: author.id } 
    });
    result.push({ ...author, books });
  }
  return result;
}
